.entity-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--foreground);
  text-decoration: none;
  min-inline-size: 0;
}
.entity-link:hover .entity-link-title { text-decoration: underline; }
.entity-link:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
  border-radius: var(--radius-sm);
}

.entity-link-icon { color: var(--muted-foreground); flex: none; }
.entity-link-title { font-weight: var(--font-weight-medium); }

/* Inline: it has to sit in a line of prose without changing its rhythm, so no
 * surface, no padding block, and the baseline stays the sentence's. */
.entity-link[data-view="inline"] {
  padding-inline: var(--space-1);
  border-radius: var(--radius-sm);
  background: var(--muted);
  vertical-align: baseline;
}

/* Card: the entity gets its own surface, which is what a link owes when it is
 * the subject of the paragraph rather than a mention inside it. */
.entity-link[data-view="card"] {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: var(--space-1) var(--space-3);
  align-items: center;
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  background: var(--card);
}
.entity-link[data-view="card"] .entity-link-icon { grid-row: 1 / span 2; }
.entity-link[data-view="card"]:hover { border-color: var(--border-strong, var(--border)); }
/* Pressed: one stop past hover, the third answer every control now gives. */
.entity-link:active .entity-link-title { color: var(--link-hover); }
.entity-link[data-view="card"]:active { background: var(--surface-hover); }
.entity-link-meta {
  grid-column: 2 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  font-size: var(--font-sm);
  color: var(--muted-foreground);
}

import "./EntityLink.css";
import type { ReactNode } from "react";
import { cn } from "../lib/cn";
import { Icon, type IconName } from "../Icon";

type View = "inline" | "card";

type Props = {
  /** What it is called where it lives — the issue key, the document title. */
  title: ReactNode;
  /** Where it goes. */
  href: string;
  /** Which system it lives in, as an icon: an audit, a document, a chat. */
  icon?: IconName;
  /** How much context the sentence owes: `inline` reads as a link inside running
   *  text, `card` gives the entity its own surface with the meta under it. The
   *  AUTHOR picks the view; the entity is the same either way. */
  view?: View;
  /** The entity's state — a <Badge>, kept out of the title so it can be read
   *  separately. */
  status?: ReactNode;
  /** Owner, date, size: shown in the card view, dropped inline. */
  meta?: ReactNode;
  className?: string;
};

/** One entity that lives ELSEWHERE, shown with enough of itself to be
 *  recognised: inline inside a sentence, or as a card with its state and its
 *  meta. Wrap it in <HoverCard> when the preview should appear on hover instead
 *  of on the page. 
 *
 * Copy: the title is the record's name; the meta says what is waiting inside it,
 * which is the reason to follow the link at all.
 */
export function EntityLink({ title, href, icon, view = "inline", status, meta, className }: Props) {
  return (
    <a className={cn("entity-link", className)} href={href} data-view={view}>
      {icon && <Icon name={icon} size={view === "card" ? "md" : "sm"} className="entity-link-icon" aria-hidden="true" />}
      <span className="entity-link-title">{title}</span>
      {status}
      {view === "card" && meta && <span className="entity-link-meta">{meta}</span>}
    </a>
  );
}
